artefacts on circles

    
        More Madness Circle
        Other forms\Dipyramid\Face Turning\More Madness Circle
        not invented
        Evgeniy Grigoriev
        2017-06-08
        
    

    
        clYellow  := 'FFFF00';
        clBlue    := '0000A0';
        clOrange  := 'FF6000';
        clRed     := 'FF0000';
        clGreen   := '008000';
        clViolett := '800080';

        R := 0.8;
        H := R / sqrt(3);

        Delta := 1.14;
        for i := 0 to 2 do begin
            x[i] := R * sin(2 * Pi / 3 * i);
            y[i] := R * cos(2 * Pi / 3 * i);
            nx[i] := -x[i] * Delta * 2 / 7;
            ny[i] := -y[i] * Delta * 2 / 7;
        end;
        nz := R * sqrt(3)/2 * Delta * 2 / 7;

        A1 := ArcCos(1/8);
        A2 := ArcCos(-3/4);

        D1 := R / 7 / sqrt(7)+0.00604750;
        D2 := R / sqrt(7);

//ShowMessage((D1 - R / 7 / sqrt(7))/ R / Delta / sqrt(7));

        RC := R * 0.25;
